#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "retained_session_scene_candidate.h"
#include "retained_fur_scene_candidate.h"
#include "gameinfo_mounts_candidate.h"
#include <algorithm>
struct FurSceneMeasurement{double wall,decoration,guides,ribbons,append;};
int main(){try{
 std::filesystem::path content=R"(D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod)";std::ifstream file(content/"gameinfo.txt",std::ios::binary);std::string text((std::istreambuf_iterator<char>(file)),{});RetainedSessionSceneCandidate scene(loadGraph("work/roundtrip-11.dmx"),2237,gameinfoMountsCandidate(text,content,content.parent_path()),4,true,true);
 auto serial=std::make_shared<RetainedFurSceneCandidate>(2552,100000,2.f,.02f,.1f,123);auto parallel=std::make_shared<RetainedFurSceneCandidate>(2552,100000,2.f,.02f,.1f,123,std::array<uint8_t,3>{220,220,220},4);
 std::vector<FurSceneMeasurement>measurements[2];
 auto sample=[&](const std::shared_ptr<RetainedFurSceneCandidate>&fur,int32_t tick,FurSceneMeasurement&m){scene.setSceneDecorationCandidate([fur](const auto&g,const auto&s,const auto&geometry,const auto&asset,auto&prepared){fur->prepare(g,s,geometry,asset,prepared);});auto start=std::chrono::steady_clock::now();auto result=scene.sample(tick);m={std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count(),result.profile.decoration,result.profile.furGuides,result.profile.furRibbons,result.profile.furAppend};if(!(m.decoration>0&&m.wall>=m.decoration&&m.decoration>=m.guides+m.ribbons+m.append))throw std::runtime_error("fur timing coverage");return result;};
 for(unsigned i=0;i<23;++i){FurSceneMeasurement a{},b{};PreparedSessionSceneCandidate first,second;int32_t tick=870833+int32_t(i%3)*1000;if(i%2){second=sample(parallel,tick,b);first=sample(serial,tick,a);}else{first=sample(serial,tick,a);second=sample(parallel,tick,b);}if(first.upload.indices!=second.upload.indices||first.upload.vertices.size()!=second.upload.vertices.size()||first.upload.opaque.size()!=second.upload.opaque.size()||first.materialAlpha!=second.materialAlpha)throw std::runtime_error("parallel fur scene topology mismatch");for(size_t n=0;n<first.upload.vertices.size();++n){const auto&x=first.upload.vertices[n],&y=second.upload.vertices[n];if(x.position!=y.position||x.normal!=y.normal||x.uv!=y.uv)throw std::runtime_error("parallel fur scene geometry mismatch");}if(i>=3){measurements[0].push_back(a);measurements[1].push_back(b);}}
 std::ofstream stages("outputs/sfm64-fur-stage-samples.csv");if(!stages)throw std::runtime_error("stage report open failed");stages<<"guide_workers,wall_ms,decoration_ms,guides_ms,camera_ribbons_ms,append_ms\n";for(unsigned mode=0;mode<2;++mode)for(auto m:measurements[mode])stages<<(mode?4:0)<<','<<m.wall<<','<<m.decoration<<','<<m.guides<<','<<m.ribbons<<','<<m.append<<'\n';stages.flush();if(!stages)throw std::runtime_error("stage report write failed");
 auto median=[](std::vector<double>v){std::sort(v.begin(),v.end());return (v[v.size()/2-1]+v[v.size()/2])*.5;};std::ofstream out("outputs/sfm64-fur-scene-preparation-benchmark.json");if(!out)throw std::runtime_error("benchmark output failed");out<<"{\n\"strands\":100000,\n\"warmup_pairs\":3,\n\"measured_pairs\":20,\n\"all_23_pairs_geometry_exact\":true,\n\"runs\":[";for(unsigned mode=0;mode<2;++mode){std::vector<double>wall,decoration;for(auto m:measurements[mode]){wall.push_back(m.wall);decoration.push_back(m.decoration);}if(mode)out<<',';out<<"{\"guide_workers\":"<<(mode?4:0)<<",\"median_scene_wall_ms\":"<<median(wall)<<",\"median_fur_decoration_ms\":"<<median(decoration)<<",\"samples\":[";for(size_t i=0;i<wall.size();++i){if(i)out<<',';out<<"{\"wall_ms\":"<<wall[i]<<",\"fur_ms\":"<<decoration[i]<<'}';}out<<"]}";}out<<"],\n\"limits\":\"One installed model. CPU scene preparation only; no GPU/presentation or native SFM comparison. Root generation excluded after warmup. Guide sampling parallel, ribbon building serial. Shared retained asset cache and four geometry workers; alternating measurement order.\"\n}\n";out.flush();if(!out)throw std::runtime_error("benchmark write failed");std::cout<<"fur_scene_benchmark_pairs=20 geometry_exact_pairs=23 decoration_timing_included=1\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
